import express from 'express';import helmet from 'helmet';import cors from 'cors';import multer from 'multer';import {openDatabase} from './db.mjs';import {modelReport,modelInput,structureOf,compareToModel} from './models.mjs';import {readableSource} from './manual.mjs';import bcrypt from 'bcryptjs';import jwt from 'jsonwebtoken';import {randomUUID,randomBytes,createCipheriv,createDecipheriv,createHash} from 'node:crypto';import fs from 'node:fs/promises';import {existsSync} from 'node:fs';import {fileURLToPath} from 'node:url';import path from 'node:path';import {spawn} from 'node:child_process';import OpenAI from 'openai';import {detectTerms,buildMap,redact,restore,leftoverPlaceholders} from './privacy.mjs';import {genderOf,genderProblems,genderRule} from './gender.mjs';import {CATEGORY_RULE,CATEGORY_RULE_SOFT,wordingProblems,metalanguageTerms,asksForScores} from './wording.mjs';import {examplesFor,STYLE_EXAMPLE_NOTE,STYLE,CLINICAL_ROLE,SYSTEM_INSTRUCTIONS,systemFor,manualRoleFor,MANUAL_FORMAT,CONCLUSION_GUIDANCE,WORD_LIMITS,promptFor,instrumentGuides,depthRule,generationParams,isReasoningModel,GENERATION,RETRY_KEEP,INSTRUMENTS,DEVOLUTIVA_AUDIENCES,devolutivaTask,devolutivaGender,DEVOLUTIVA_SYSTEM} from './prompts.mjs';import rateLimit from 'express-rate-limit';import {dictationConfig,clientSecretRequest,safetyId,dictationError} from './dictation.mjs';import {consistencyChecks,planChecks} from './checks.mjs';import {newSecret,verifyTotp,otpauthUri} from './totp.mjs';import {qualityBySection} from './quality.mjs';import {packBackup,MIN_BACKUP_PASSWORD} from './backup.mjs';import {ROLES,ROLE_NAMES,normEmail,checkPassword,newUserInput,userChanges,guardChange,publicUser} from './users.mjs';
const app=express();app.use(helmet());app.use(cors({origin:process.env.CORS_ORIGIN||'http://localhost:9091'}));app.use(express.json({limit:'2mb'}));app.use('/api',rateLimit({windowMs:60_000,limit:Number(process.env.API_RATE_LIMIT)||120,standardHeaders:'draft-7',legacyHeaders:false}));

const STORAGE=path.resolve(process.env.STORAGE_DIR||'./storage');const KEY=process.env.FILE_ENCRYPTION_KEY;const JWT=process.env.JWT_SECRET;
const HERE=path.dirname(fileURLToPath(import.meta.url));
// Embedded SQLite file inside the project folder: copying the folder copies the data (with storage/ and .env).
const DB_FILE=path.resolve(process.env.DB_FILE||'./data/neurolaudos.db');
const SCHEMA=[path.resolve(HERE,'../db/schema.sql'),path.resolve(HERE,'../../db/schema.sql')].find(p=>existsSync(p));
// Worker lives in /app/worker (Docker) or <repo>/worker (local). WORKER_PATH overrides both.
const WORKER=[process.env.WORKER_PATH,path.resolve(HERE,'../worker/docx_worker.py'),path.resolve(HERE,'../../worker/docx_worker.py')].filter(Boolean).find(p=>existsSync(p));
const PYTHON=process.env.PYTHON_BIN||(process.platform==='win32'?'python':'python3');
const configProblems=[!JWT||JWT.length<32||/REPLACE/.test(JWT)?'JWT_SECRET (32+ caracteres aleatórios)':null,!/^[a-f0-9]{64}$/i.test(KEY||'')?'FILE_ENCRYPTION_KEY (64 hex)':null,!WORKER?'worker/docx_worker.py não encontrado (defina WORKER_PATH)':null].filter(Boolean);
if(!SCHEMA)configProblems.push('db/schema.sql não encontrado');
if(configProblems.length){console.error('Configuração inválida em api/.env: '+configProblems.join('; '));process.exit(1)}
const pool=openDatabase(DB_FILE,SCHEMA);
const wrap=f=>(req,res,next)=>Promise.resolve(f(req,res)).catch(next);
const fail=(code,message)=>Object.assign(new Error(message),{status:code});
function encryptionKey(){if(!/^[a-f0-9]{64}$/i.test(KEY||''))throw fail(503,'Encryption key not configured');return Buffer.from(KEY,'hex')}
function encrypt(data){const nonce=randomBytes(12),cipher=createCipheriv('aes-256-gcm',encryptionKey(),nonce);return Buffer.concat([nonce,cipher.update(data),cipher.final(),cipher.getAuthTag()])}
function decrypt(data){const nonce=data.subarray(0,12),tag=data.subarray(data.length-16),body=data.subarray(12,data.length-16);const c=createDecipheriv('aes-256-gcm',encryptionKey(),nonce);c.setAuthTag(tag);return Buffer.concat([c.update(body),c.final()])}
async function store(bytes){await fs.mkdir(STORAGE,{recursive:true,mode:0o700});const id=randomUUID();await fs.writeFile(path.join(STORAGE,id+'.bin'),encrypt(bytes),{mode:0o600});return id+'.bin'}
async function readStorage(name){if(!/^[a-f0-9-]+\.bin$/.test(name))throw fail(400,'Invalid file');return decrypt(await fs.readFile(path.join(STORAGE,name)))}
// Every request re-reads the account: a deactivated user, a changed role or a reset password (token_version) takes
// effect at once, without waiting for the 8 h token to expire. The role always comes from the database, not the token.
const FIRST_LOGIN_ROUTES=['/api/me','/api/me/password'];
async function auth(req,res,next){
 let u;
 try{const token=(req.headers.authorization||'').replace(/^Bearer /,'');const p=jwt.verify(token,JWT,{algorithms:['HS256']});[[u]]=await pool.execute('SELECT id,email,name,role,active,token_version,must_change_password FROM users WHERE id=?',[p.id]);if(!u||!u.active||Number(u.token_version||0)!==Number(p.tv||0))u=null}catch{u=null}
 if(!u)return res.status(401).json({error:'unauthorized'});
 // A temporary password set by the admin must be replaced before anything else.
 if(u.must_change_password&&!FIRST_LOGIN_ROUTES.includes(req.originalUrl.split('?')[0]))return res.status(403).json({error:'Troque a senha temporária antes de continuar.',code:'password_change_required'});
 req.user={id:u.id,role:u.role,email:u.email,name:u.name};next();
}
const signToken=u=>jwt.sign({id:u.id,tv:Number(u.token_version||0)},JWT,{algorithm:'HS256',expiresIn:'8h'});
function role(...roles){return(req,res,next)=>roles.includes(req.user.role)?next():res.status(403).json({error:'forbidden'})}
async function audit(req,action,ev=null){await pool.execute('INSERT INTO audit_logs(actor_id,evaluation_id,action) VALUES(?,?,?)',[req.user?.id||null,ev,action])}
async function evaluation(id){const [[e]]=await pool.execute('SELECT e.*,p.name patient_name,p.birth_date,m.name model_name,m.instructions_json model_instructions_json FROM evaluations e JOIN patients p ON p.id=e.patient_id LEFT JOIN report_models m ON m.id=e.model_id WHERE e.id=?',[id]);if(!e)throw fail(404,'Avaliação não encontrada');return e}
async function docx(op,args,stdin){return await new Promise((resolve,reject)=>{const p=spawn(PYTHON,[WORKER,op,...args],{timeout:30000,windowsHide:true});const chunks=[];let err='';p.stdout.on('data',x=>chunks.push(x));p.stderr.on('data',x=>err+=x);p.on('error',reject);p.on('close',code=>{if(code!==0)return reject(fail(500,`DOCX worker: ${err.slice(0,300)}`));try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')))}catch{reject(fail(500,'Invalid worker output'))}});p.stdin.end(stdin?JSON.stringify(stdin):undefined)})}
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:15*1024*1024},fileFilter:(req,file,cb)=>cb(null,file.originalname.toLowerCase().endsWith('.docx'))});
const authLimiter=rateLimit({windowMs:15*60_000,limit:10,standardHeaders:'draft-7',legacyHeaders:false,skipSuccessfulRequests:true,message:{error:'Muitas tentativas. Aguarde 15 minutos.'}});
app.get('/api/health',wrap(async(req,res)=>{let db=false;try{await pool.query('SELECT 1');db=true}catch{}res.status(db?200:503).json({ok:db,db,service:'neurolaudos',version:'0.3.0'})}));
app.post('/api/setup',authLimiter,wrap(async(req,res)=>{const [[{count}]]=await pool.query('SELECT COUNT(*) count FROM users');if(count)throw fail(403,'Setup disabled');if(!JWT||JWT.length<32)throw fail(503,'Set JWT_SECRET');encryptionKey();const {email,name,password}=req.body;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email||''))||!name||!password||password.length<14)throw fail(400,'Administrator password must have at least 14 characters');const id=randomUUID();await pool.execute('INSERT INTO users(id,email,name,password_hash,role) VALUES(?,?,?,?,?)',[id,email,name,await bcrypt.hash(password,12),'admin']);res.status(201).json({id,email})}));
app.post('/api/login',authLimiter,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT * FROM users WHERE lower(email)=?',[normEmail(req.body?.email)]);if(!u||!await bcrypt.compare(String(req.body?.password||''),u.password_hash))throw fail(401,'E-mail ou senha incorretos');if(!u.active)throw fail(403,'Conta desativada. Fale com o administrador.');if(u.totp_enabled_at){if(!req.body?.code)return res.json({mfa_required:true});const step=verifyTotp(totpSecretOf(u.totp_secret),req.body.code,Number(u.totp_last_step??-1));if(step===null)throw fail(401,'Código inválido. Confira o horário do celular e tente de novo.');await pool.execute('UPDATE users SET totp_last_step=? WHERE id=?',[step,u.id])}await pool.execute('UPDATE users SET last_login_at=CURRENT_TIMESTAMP WHERE id=?',[u.id]);res.json({token:signToken(u),...publicUser(u)})}));
// Always the same answer, whether or not the e-mail exists, so the form does not reveal who has an account.
app.post('/api/password-requests',authLimiter,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT id,active FROM users WHERE lower(email)=?',[normEmail(req.body?.email)]);if(u?.active){const [[open]]=await pool.execute('SELECT COUNT(*) n FROM password_requests WHERE user_id=? AND handled_at IS NULL',[u.id]);if(!Number(open.n)){await pool.execute('INSERT INTO password_requests(user_id) VALUES(?)',[u.id]);await pool.execute("INSERT INTO audit_logs(actor_id,action) VALUES(?,'password_reset_requested')",[u.id])}}res.status(202).json({ok:true})}));
app.get('/api/me',auth,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);res.json(publicUser(u))}));
// Changing the password ends every other session (token_version) and hands back a fresh token for this one.
// A wrong current password is 400, not 401, so the screen does not log the user out.
app.put('/api/me/password',auth,authLimiter,wrap(async(req,res)=>{const {current,next}=req.body||{};checkPassword(next);const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);if(!u||!await bcrypt.compare(String(current||''),u.password_hash))throw fail(400,'Senha atual incorreta');if(next===current)throw fail(400,'A nova senha precisa ser diferente da atual');await pool.execute('UPDATE users SET password_hash=?,must_change_password=0,token_version=token_version+1 WHERE id=?',[await bcrypt.hash(next,12),u.id]);await audit(req,'password_changed');const [[fresh]]=await pool.execute('SELECT * FROM users WHERE id=?',[u.id]);res.json({ok:true,token:signToken(fresh),...publicUser(fresh)})}));
// ---- Review workflow: the assistant sends the evaluation for review; the psychologist can ask for corrections. ----
// A correction request takes the evaluation back to whoever prepared it (submitted_at cleared) until it is sent again.
async function notesOf(id){const [rows]=await pool.execute('SELECT n.*,a.name author_name,r.name resolved_by_name FROM review_notes n LEFT JOIN users a ON a.id=n.author_id LEFT JOIN users r ON r.id=n.resolved_by WHERE n.evaluation_id=? ORDER BY n.created_at',[id]);return rows}
async function workflowOf(id){const [[e]]=await pool.execute('SELECT e.submitted_at,u.name submitted_by_name FROM evaluations e LEFT JOIN users u ON u.id=e.submitted_by WHERE e.id=?',[id]);return {submitted_at:e?.submitted_at||null,submitted_by_name:e?.submitted_by_name||null,notes:await notesOf(id)}}
app.get('/api/evaluations/:id/review',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);res.json(await workflowOf(e.id))}));
app.post('/api/evaluations/:id/submit',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação já aprovada');const [docs]=await pool.execute('SELECT kind FROM documents WHERE evaluation_id=?',[e.id]);if(!docs.some(d=>d.kind==='base')||!docs.some(d=>d.kind==='anamnesis'))throw fail(409,'Envie o arquivo base e a anamnese antes de mandar para revisão');const [[open]]=await pool.execute('SELECT COUNT(*) n FROM review_notes WHERE evaluation_id=? AND resolved_at IS NULL',[e.id]);if(Number(open.n))throw fail(409,'Marque os pedidos de correção como resolvidos antes de enviar de novo');await pool.execute('UPDATE evaluations SET submitted_at=CURRENT_TIMESTAMP,submitted_by=? WHERE id=?',[req.user.id,e.id]);await audit(req,'evaluation_submitted',e.id);res.json(await workflowOf(e.id))}));
app.post('/api/evaluations/:id/notes',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação aprovada');const text=String(req.body?.text||'').trim();if(text.length<3||text.length>4000)throw fail(400,'Escreva o pedido (3 a 4.000 caracteres)');await pool.execute('INSERT INTO review_notes(id,evaluation_id,author_id,text) VALUES(?,?,?,?)',[randomUUID(),e.id,req.user.id,text]);await pool.execute('UPDATE evaluations SET submitted_at=NULL WHERE id=?',[e.id]);await audit(req,'correction_requested',e.id);res.status(201).json(await workflowOf(e.id))}));
app.post('/api/evaluations/:id/notes/:nid/resolve',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const r=req.body?.resolved!==false;const [x]=await pool.execute(`UPDATE review_notes SET resolved_at=${r?'CURRENT_TIMESTAMP':'NULL'},resolved_by=? WHERE id=? AND evaluation_id=?`,[r?req.user.id:null,String(req.params.nid),e.id]);if(!x.affectedRows)throw fail(404,'Pedido não encontrado');await audit(req,r?'correction_resolved':'correction_reopened',e.id);res.json(await workflowOf(e.id))}));
// ---- Standard texts (textos-padrão): shared by the clinic, typed by the psychologist, inserted in the editor by hand. ----
function snippetInput(b){const title=String(b?.title||'').replace(/\s+/g,' ').trim(),text=String(b?.text||'').trim(),key=b?.section_key?String(b.section_key):null;if(title.length<2||title.length>120)throw fail(400,'Dê um título (2 a 120 caracteres)');if(text.length<2||text.length>8000)throw fail(400,'O texto deve ter entre 2 e 8.000 caracteres');if(key&&!SECTION_KEYS.includes(key))throw fail(400,'Seção inválida');return {title,text,key}}
app.get('/api/snippets',auth,wrap(async(req,res)=>{const [rows]=await pool.query('SELECT s.id,s.title,s.text,s.section_key,s.updated_at,u.name author FROM text_snippets s LEFT JOIN users u ON u.id=s.created_by ORDER BY s.title');res.json(rows)}));
app.post('/api/snippets',auth,role('admin','psychologist'),wrap(async(req,res)=>{const v=snippetInput(req.body);const id=randomUUID();await pool.execute('INSERT INTO text_snippets(id,title,text,section_key,created_by) VALUES(?,?,?,?,?)',[id,v.title,v.text,v.key,req.user.id]);await audit(req,'snippet_created');res.status(201).json({id})}));
app.put('/api/snippets/:id',auth,role('admin','psychologist'),wrap(async(req,res)=>{const v=snippetInput(req.body);const [r]=await pool.execute('UPDATE text_snippets SET title=?,text=?,section_key=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[v.title,v.text,v.key,String(req.params.id)]);if(!r.affectedRows)throw fail(404,'Texto-padrão não encontrado');await audit(req,'snippet_updated');res.json({ok:true})}));
app.delete('/api/snippets/:id',auth,role('admin','psychologist'),wrap(async(req,res)=>{const [r]=await pool.execute('DELETE FROM text_snippets WHERE id=?',[String(req.params.id)]);if(!r.affectedRows)throw fail(404,'Texto-padrão não encontrado');await audit(req,'snippet_deleted');res.json({ok:true})}));
// ---- Devolutiva: plain-language letter for the family (or the adult patient), a separate document from the report. ----
// Rule 10 by nature: it reads only the texts of the APPROVED report (never tables or the anamnesis). AI draft only:
// saved with history, edited and approved by the psychologist; the Word file only after approval.
const devolutivaSources=()=>['demanda',...INTERPRETATION_KEYS,'conclusao','recomendacoes']; // a function: the section lists are declared further down
async function devolutivaOf(id){const [[d]]=await pool.execute('SELECT d.*,u.name approved_by_name FROM devolutivas d LEFT JOIN users u ON u.id=d.approved_by WHERE d.evaluation_id=?',[id]);return d||null}
const defaultAudience=e=>{const y=parseInt(ageText(e.birth_date,e.end_date),10);return Number.isFinite(y)&&y>=18&&!/mes/.test(ageText(e.birth_date,e.end_date))?'paciente':'familia'};
async function saveDevolutiva(req,e,{content,audience,status,warnings}){
 const prev=await devolutivaOf(e.id);
 if(prev){await pool.execute('INSERT INTO devolutiva_history(evaluation_id,version,content,actor_id) VALUES(?,?,?,?)',[e.id,prev.version,prev.content,req.user.id]);
  await pool.execute('UPDATE devolutivas SET content=?,audience=?,status=?,warnings_json=?,version=version+1,approved_by=?,approved_at=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE evaluation_id=?',[content,audience||prev.audience,status,JSON.stringify(warnings||[]),status==='approved'?req.user.id:null,status==='approved'?new Date():null,req.user.id,e.id])}
 else await pool.execute('INSERT INTO devolutivas(evaluation_id,content,audience,status,warnings_json,approved_by,approved_at,updated_by) VALUES(?,?,?,?,?,?,?,?)',[e.id,content,audience||defaultAudience(e),status,JSON.stringify(warnings||[]),status==='approved'?req.user.id:null,status==='approved'?new Date():null,req.user.id]);
 return devolutivaOf(e.id);
}
app.get('/api/evaluations/:id/devolutiva',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const [[h]]=await pool.execute('SELECT COUNT(*) n FROM devolutiva_history WHERE evaluation_id=?',[e.id]);res.json({devolutiva:await devolutivaOf(e.id),report_approved:e.status==='approved',default_audience:defaultAudience(e),versions:Number(h.n)})}));
app.post('/api/evaluations/:id/devolutiva/generate',auth,role('admin','psychologist'),wrap(async(req,res)=>{
 const e=await evaluation(req.params.id);if(e.status!=='approved')throw fail(409,'Aprove o laudo antes de gerar a devolutiva');
 const cur=await devolutivaOf(e.id);if(cur?.status==='approved')throw fail(409,'Devolutiva aprovada: reabra para gerar de novo');requireAiMode(e);
 const [[cfg]]=await pool.query('SELECT * FROM ai_settings WHERE id=1');if(!cfg.enabled||process.env.AI_ENABLED!=='true'||process.env.ALLOW_EXTERNAL_AI!=='true'||!process.env.OPENAI_API_KEY)throw fail(503,'AI disabled until privacy and API configuration approved');
 const audience=DEVOLUTIVA_AUDIENCES[req.body?.audience]?req.body.audience:defaultAudience(e);
 const [rows]=await pool.execute("SELECT section_key,content FROM sections WHERE evaluation_id=? AND status='approved' AND TRIM(content)<>''",[e.id]);
 const textos=Object.fromEntries(devolutivaSources().map(k=>[k,rows.find(r=>r.section_key===k)?.content]).filter(([,v])=>v).map(([k,v])=>[SECTION_NAMES[k],v]));
 if(!textos[SECTION_NAMES.conclusao]&&!textos[SECTION_NAMES.recomendacoes])throw fail(409,'O laudo aprovado precisa ter conclusão ou recomendações para a devolutiva');
 const files=await loadFiles(e);const entries=privacyMap(e,files);const gender=genderOf(e.sex||files.base.identification?.['Sexo']);
 const notes=String(req.body?.notes||'').trim().slice(0,4000);
 const prompt=redact(devolutivaTask(audience)+(notes?' ORIENTAÇÕES DA PSICÓLOGA, com prioridade no foco, no tom e na extensão (nunca para inventar dados ou acrescentar diagnóstico): '+notes:'')+' '+devolutivaGender(gender),entries);
 const data=redact({textos_do_laudo:textos,idade_em_anos:ageText(e.birth_date,e.end_date)||null},entries);
 let result;try{result=await generateText(prompt,data,cfg.model,DEVOLUTIVA_SYSTEM)}catch(err){if(err.usage)await recordUsage(req,e.id,'devolutiva',cfg.model,err.usage);throw err}
 await recordUsage(req,e.id,'devolutiva',cfg.model,result.usage);
 const problems=t=>wordingProblems(t,{categories:true,numbers:true});
 if(problems(result.text).length){const retry=await generateText(prompt+' ATENÇÃO: a versão anterior trouxe '+problems(result.text).join(' e ')+'. Reescreva o texto inteiro sem nenhum algarismo e sem categorias de desempenho.'+RETRY_KEEP,data,cfg.model,DEVOLUTIVA_SYSTEM).catch(()=>null);if(retry){await recordUsage(req,e.id,'devolutiva',cfg.model,retry.usage);result=retry}}
 const text=restore(result.text,entries);const warnings=(result.warnings||[]).map(w=>restore(String(w),entries));
 const left=leftoverPlaceholders(text);if(left.length)warnings.push('Marcadores não reconhecidos no texto: '+left.join(', ')+'. Troque pelo dado correto antes de aprovar.');
 const p=problems(text);if(p.length)warnings.push('Texto contém '+p.join(' e ')+'. Revise antes de aprovar.');
 const d=await saveDevolutiva(req,e,{content:text,audience,status:'draft',warnings});await audit(req,'devolutiva_generated',e.id);res.json({devolutiva:d});
}));
app.put('/api/evaluations/:id/devolutiva',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status!=='approved')throw fail(409,'Aprove o laudo antes da devolutiva');const cur=await devolutivaOf(e.id);if(cur?.status==='approved'&&req.body?.approve!==true)throw fail(409,'Devolutiva aprovada: reabra para editar');const content=String(req.body?.content||'').trim();if(content.length<20)throw fail(400,'Escreva o texto da devolutiva');if(content.length>30000)throw fail(400,'Texto longo demais');const audience=DEVOLUTIVA_AUDIENCES[req.body?.audience]?req.body.audience:undefined;const approve=req.body?.approve===true;const d=await saveDevolutiva(req,e,{content,audience,status:approve?'approved':'draft',warnings:approve?[]:JSON.parse(cur?.warnings_json||'[]')});await audit(req,approve?'devolutiva_approved':'devolutiva_edited',e.id);res.json({devolutiva:d})}));
app.post('/api/evaluations/:id/devolutiva/reopen',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);const cur=await devolutivaOf(e.id);if(!cur)throw fail(404,'Sem devolutiva');await pool.execute("UPDATE devolutivas SET status='draft',approved_by=NULL,approved_at=NULL WHERE evaluation_id=?",[e.id]);await audit(req,'devolutiva_reopened',e.id);res.json({devolutiva:await devolutivaOf(e.id)})}));
app.post('/api/evaluations/:id/devolutiva/export',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);const d=await devolutivaOf(e.id);if(d?.status!=='approved')throw fail(409,'Aprove a devolutiva antes de baixar');await fs.mkdir(STORAGE,{recursive:true,mode:0o700});const out=path.join(STORAGE,randomUUID()+'.docx');try{await docx('letter',[],{out,title:'Devolutiva da avaliação neuropsicológica',subtitle:e.patient_name,content:d.content});const bytes=await fs.readFile(out);await audit(req,'devolutiva_export',e.id);res.set('Content-Type',DOCX_TYPE);res.set('Content-Disposition','attachment; filename="devolutiva.docx"');res.send(bytes)}finally{await fs.rm(out,{force:true})}}));
// ---- Backup and retention ----
// Automatic encrypted backup once a day (this computer's key), kept BACKUP_KEEP times; a password copy can be downloaded
// to keep elsewhere (it opens on another computer). Restoring: npm run backup:restaurar <arquivo> with the system closed.
const BACKUP_DIR=path.resolve(process.env.BACKUP_DIR||'./backups');const BACKUP_KEEP=Math.max(1,Number(process.env.BACKUP_KEEP)||14);
const RETENTION_YEARS=Math.max(1,Number(process.env.RETENTION_YEARS)||5);
async function backupEntries(){
 await fs.mkdir(BACKUP_DIR,{recursive:true,mode:0o700});const tmp=path.join(BACKUP_DIR,'snapshot-'+randomUUID()+'.db');
 try{await pool.execute(`VACUUM INTO '${tmp.replace(/'/g,"''")}'`);const db=await fs.readFile(tmp);
  const names=existsSync(STORAGE)?(await fs.readdir(STORAGE)).filter(n=>/^[a-f0-9-]+\.bin$/.test(n)):[];
  return [{name:'db',bytes:db},...await Promise.all(names.map(async n=>({name:'storage/'+n,bytes:await fs.readFile(path.join(STORAGE,n))})))]}
 finally{await fs.rm(tmp,{force:true})}
}
async function backupCounts(){const c=async t=>Number((await pool.query(`SELECT COUNT(*) n FROM ${t}`))[0][0].n);return {evaluations:await c('evaluations'),patients:await c('patients'),documents:await c('documents')}}
async function listBackups(){if(!existsSync(BACKUP_DIR))return [];const out=[];for(const name of await fs.readdir(BACKUP_DIR)){if(!/^backup-[\w-]+\.nlbk$/.test(name))continue;const st=await fs.stat(path.join(BACKUP_DIR,name));out.push({name,size:st.size,created_at:st.mtime.toISOString()})}return out.sort((a,b)=>b.created_at.localeCompare(a.created_at))}
let backupRunning=null;
async function makeBackup(reason){
 if(backupRunning)return backupRunning;
 backupRunning=(async()=>{const entries=await backupEntries();const buf=packBackup(entries,{reason,counts:await backupCounts()},{machineKey:KEY});
  const name=`backup-${new Date().toISOString().replace(/[:.]/g,'-')}.nlbk`;await fs.writeFile(path.join(BACKUP_DIR,name),buf,{mode:0o600});
  for(const old of (await listBackups()).slice(BACKUP_KEEP))await fs.rm(path.join(BACKUP_DIR,old.name),{force:true});
  return {name,size:buf.length}})().finally(()=>{backupRunning=null});
 return backupRunning;
}
async function autoBackup(){try{if(process.env.BACKUP_AUTO==='false')return;const last=(await listBackups())[0];if(!last||Date.now()-Date.parse(last.created_at)>23*3600_000){const b=await makeBackup('automatico');console.log('Backup automático criado: '+b.name)}}catch(e){console.error('Backup automático falhou:',e.message)}}
app.get('/api/backups',auth,role('admin'),wrap(async(req,res)=>{res.json({dir:BACKUP_DIR,keep:BACKUP_KEEP,auto:process.env.BACKUP_AUTO!=='false',backups:await listBackups()})}));
app.post('/api/backups',auth,role('admin'),wrap(async(req,res)=>{const b=await makeBackup('manual');await audit(req,'backup_created');res.status(201).json({...b,backups:await listBackups()})}));
// Password copy: generated on the fly and downloaded, never stored here. It carries the file key, encrypted by the password.
app.post('/api/backups/export',auth,role('admin'),authLimiter,wrap(async(req,res)=>{const password=String(req.body?.password||'');if(password.length<MIN_BACKUP_PASSWORD)throw fail(400,`A senha do backup precisa ter pelo menos ${MIN_BACKUP_PASSWORD} caracteres`);const buf=packBackup(await backupEntries(),{reason:'copia_com_senha',counts:await backupCounts(),file_key:KEY},{password});await audit(req,'backup_exported');res.set('Content-Type','application/octet-stream');res.set('Content-Disposition',`attachment; filename="neurolaudos-${new Date().toISOString().slice(0,10)}.nlbk"`);res.set('Cache-Control','no-store');res.send(buf)}));
// Retention: approved reports are kept RETENTION_YEARS after approval (minimum the professional rules require); past that
// the list shows them for a conscious decision. Nothing is deleted automatically.
app.get('/api/retention',auth,role('admin','psychologist'),wrap(async(req,res)=>{const [rows]=await pool.query("SELECT e.id,e.approved_at,e.created_at,p.name patient_name FROM evaluations e JOIN patients p ON p.id=e.patient_id WHERE e.status='approved' AND e.approved_at IS NOT NULL ORDER BY e.approved_at");const now=new Date(),soon=new Date(now.getTime()+90*864e5);const until=a=>{const d=new Date(a);d.setFullYear(d.getFullYear()+RETENTION_YEARS);return d};const list=rows.map(r=>({...r,keep_until:until(r.approved_at).toISOString().slice(0,10)}));res.json({years:RETENTION_YEARS,expired:list.filter(r=>until(r.approved_at)<=now),soon:list.filter(r=>until(r.approved_at)>now&&until(r.approved_at)<=soon)})}));
// ---- Assessment plan, sessions and consent ----
// The psychologist plans which instruments to apply; whoever applies them marks each one. Sessions (anamnese, application,
// feedback) feed the week on the dashboard.
// Mode: a 'manual' evaluation never calls the AI (API, ChatGPT request or devolutiva); the professional writes everything.
const SESSION_KINDS=['anamnese','aplicacao','devolutiva','outra'];
const AI_MODES=['ai','manual'];
// Closing "Cidade, data." line of the report: empty keeps what the base document says.
app.put('/api/evaluations/:id/place-date',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação aprovada: travada');const v=String(req.body?.value||'').replace(/\s+/g,' ').trim();if(v.length>120)throw fail(400,'Local e data: no máximo 120 caracteres');await pool.execute('UPDATE evaluations SET place_date=? WHERE id=?',[v||null,e.id]);await audit(req,'place_date_updated',e.id);res.json({place_date:v||null})}));
function requireAiMode(e){if(e.ai_mode==='manual')throw fail(409,'Avaliação manual: a IA está desligada nesta avaliação. Para usar a IA, mude para Com IA em Identificação.')}
app.put('/api/evaluations/:id/mode',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação aprovada: travada');const mode=String(req.body?.mode||'');if(!AI_MODES.includes(mode))throw fail(400,'Modo inválido');await pool.execute('UPDATE evaluations SET ai_mode=? WHERE id=?',[mode,e.id]);await audit(req,'mode_'+mode,e.id);res.json({ai_mode:mode})}));
async function planOf(id){const [items]=await pool.execute('SELECT i.*,u.name applied_by_name FROM evaluation_plan i LEFT JOIN users u ON u.id=i.applied_by WHERE i.evaluation_id=? ORDER BY i.created_at',[id]);const [sessions]=await pool.execute('SELECT * FROM evaluation_sessions WHERE evaluation_id=? ORDER BY date,time',[id]);const [[c]]=await pool.execute('SELECT e.consent_care_at,e.consent_ai_at,e.consent_note,u.name consent_by_name FROM evaluations e LEFT JOIN users u ON u.id=e.consent_by WHERE e.id=?',[id]);return {items,sessions,consent:{...c,required:false},catalog:INSTRUMENTS.map(i=>i.name)}}
const dateIn=v=>/^\d{4}-\d{2}-\d{2}$/.test(v||'')?v:null,timeIn=v=>/^\d{2}:\d{2}$/.test(v||'')?v:null,textIn=(v,n)=>String(v||'').replace(/\s+/g,' ').trim().slice(0,n);
app.get('/api/evaluations/:id/plan',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);res.json(await planOf(e.id))}));
app.post('/api/evaluations/:id/plan',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status==='approved')throw fail(409,'Avaliação aprovada');const names=(Array.isArray(req.body?.instruments)?req.body.instruments:[req.body?.instrument]).map(v=>textIn(v,120)).filter(v=>v.length>=2);if(!names.length)throw fail(400,'Informe o instrumento');const [have]=await pool.execute('SELECT lower(instrument) n FROM evaluation_plan WHERE evaluation_id=?',[e.id]);const seen=new Set(have.map(x=>x.n));for(const n of names)if(!seen.has(n.toLowerCase())){seen.add(n.toLowerCase());await pool.execute('INSERT INTO evaluation_plan(id,evaluation_id,instrument,created_by) VALUES(?,?,?,?)',[randomUUID(),e.id,n,req.user.id])}await audit(req,'plan_updated',e.id);res.status(201).json(await planOf(e.id))}));
app.put('/api/evaluations/:id/plan/:item',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const status=['planned','applied','not_applied'].includes(req.body?.status)?req.body.status:null;if(!status)throw fail(400,'Situação inválida');const [r]=await pool.execute(`UPDATE evaluation_plan SET status=?,session_id=?,note=?,applied_at=${status==='applied'?'CURRENT_TIMESTAMP':'NULL'},applied_by=? WHERE id=? AND evaluation_id=?`,[status,req.body?.session_id?String(req.body.session_id):null,textIn(req.body?.note,300)||null,status==='applied'?req.user.id:null,String(req.params.item),e.id]);if(!r.affectedRows)throw fail(404,'Item não encontrado');await audit(req,'plan_item_'+status,e.id);res.json(await planOf(e.id))}));
app.delete('/api/evaluations/:id/plan/:item',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);const [r]=await pool.execute('DELETE FROM evaluation_plan WHERE id=? AND evaluation_id=?',[String(req.params.item),e.id]);if(!r.affectedRows)throw fail(404,'Item não encontrado');await audit(req,'plan_updated',e.id);res.json(await planOf(e.id))}));
function sessionIn(b){const date=dateIn(b?.date);if(!date)throw fail(400,'Informe a data da sessão');const kind=SESSION_KINDS.includes(b?.kind)?b.kind:'aplicacao';return {date,time:timeIn(b?.time),kind,note:textIn(b?.note,300)||null,done:b?.done===true?1:0}}
app.post('/api/evaluations/:id/sessions',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const v=sessionIn(req.body);await pool.execute('INSERT INTO evaluation_sessions(id,evaluation_id,date,time,kind,note,done,created_by) VALUES(?,?,?,?,?,?,?,?)',[randomUUID(),e.id,v.date,v.time,v.kind,v.note,v.done,req.user.id]);await audit(req,'session_scheduled',e.id);res.status(201).json(await planOf(e.id))}));
app.put('/api/evaluations/:id/sessions/:sid',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const v=sessionIn(req.body);const [r]=await pool.execute('UPDATE evaluation_sessions SET date=?,time=?,kind=?,note=?,done=? WHERE id=? AND evaluation_id=?',[v.date,v.time,v.kind,v.note,v.done,String(req.params.sid),e.id]);if(!r.affectedRows)throw fail(404,'Sessão não encontrada');res.json(await planOf(e.id))}));
app.delete('/api/evaluations/:id/sessions/:sid',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);await pool.execute('UPDATE evaluation_plan SET session_id=NULL WHERE session_id=?',[String(req.params.sid)]);const [r]=await pool.execute('DELETE FROM evaluation_sessions WHERE id=? AND evaluation_id=?',[String(req.params.sid),e.id]);if(!r.affectedRows)throw fail(404,'Sessão não encontrada');await audit(req,'session_removed',e.id);res.json(await planOf(e.id))}));
app.get('/api/sessions',auth,wrap(async(req,res)=>{const from=dateIn(req.query.from)||new Date().toISOString().slice(0,10);const to=dateIn(req.query.to)||new Date(Date.now()+7*864e5).toISOString().slice(0,10);const [rows]=await pool.execute('SELECT s.*,p.name patient_name FROM evaluation_sessions s JOIN evaluations e ON e.id=s.evaluation_id JOIN patients p ON p.id=e.patient_id WHERE s.date>=? AND s.date<=? ORDER BY s.date,s.time LIMIT 200',[from,to]);res.json(rows)}));
app.put('/api/evaluations/:id/consent',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);const care=req.body?.care===true,ai=req.body?.ai===true;await pool.execute(`UPDATE evaluations SET consent_care_at=${care?'COALESCE(consent_care_at,CURRENT_TIMESTAMP)':'NULL'},consent_ai_at=${ai?'COALESCE(consent_ai_at,CURRENT_TIMESTAMP)':'NULL'},consent_by=?,consent_note=? WHERE id=?`,[req.user.id,textIn(req.body?.note,300)||null,e.id]);await audit(req,'consent_'+(care?'care':'nocare')+'_'+(ai?'ai':'noai'),e.id);res.json(await planOf(e.id))}));
// ---- AI quality, previous evaluation and the instrument library ----
// Quality: for approved sections that came from the AI, how much the text was changed (see quality.mjs).
app.get('/api/stats/ai-quality',auth,role('admin','psychologist'),wrap(async(req,res)=>{const days=Math.min(Math.max(Number(req.query.days)||365,1),3650);const since=new Date(Date.now()-days*864e5).toISOString();const [rows]=await pool.execute("SELECT s.section_key,s.ai_text,s.content FROM sections s WHERE s.status='approved' AND s.ai_text IS NOT NULL AND COALESCE(s.approved_at,s.updated_at)>=?",[since]);res.json({days,sections:qualityBySection(rows).map(r=>({...r,name:SECTION_NAMES[r.section_key]||r.section_key}))})}));
// Re-evaluation: the approved texts of the patient's previous approved evaluation, shown beside each section (read only;
// never sent to the AI, which keeps rule 10).
app.get('/api/evaluations/:id/previous',auth,wrap(async(req,res)=>{const e=await evaluation(req.params.id);const [[prev]]=await pool.execute("SELECT id,start_date,approved_at,created_at FROM evaluations WHERE patient_id=? AND id<>? AND status='approved' AND created_at<=? ORDER BY created_at DESC LIMIT 1",[e.patient_id,e.id,e.created_at]);if(!prev)return res.json({previous:null});const [rows]=await pool.execute("SELECT section_key,content FROM sections WHERE evaluation_id=? AND status='approved'",[prev.id]);res.json({previous:{...prev,sections:Object.fromEntries(rows.map(r=>[r.section_key,r.content]))}})}));
// Instrument library: the guides sent to the AI (prompts.mjs) and the clinic's own version of each, when written.
async function guideOverrides(){const [rows]=await pool.query('SELECT id,guide FROM instrument_guides');return Object.fromEntries(rows.map(r=>[r.id,r.guide]))}
app.get('/api/instruments',auth,wrap(async(req,res)=>{const own=await guideOverrides();const [used]=await pool.query('SELECT lower(instrument) n,COUNT(DISTINCT evaluation_id) c FROM evaluation_plan GROUP BY lower(instrument)');const uses=Object.fromEntries(used.map(u=>[u.n,Number(u.c)]));res.json(INSTRUMENTS.map(i=>({id:i.id,name:i.name,multi:!!i.multi,default_guide:i.guide,custom_guide:own[i.id]||null,planned_in:uses[i.name.toLowerCase()]||0})))}));
app.put('/api/instruments/:id',auth,role('admin','psychologist'),wrap(async(req,res)=>{const i=INSTRUMENTS.find(x=>x.id===req.params.id);if(!i)throw fail(404,'Instrumento não encontrado');const guide=String(req.body?.guide||'').trim();if(guide&&(guide.length<30||guide.length>6000))throw fail(400,'O guia deve ter entre 30 e 6.000 caracteres');if(!guide||guide===i.guide)await pool.execute('DELETE FROM instrument_guides WHERE id=?',[i.id]);else await pool.execute('INSERT INTO instrument_guides(id,guide,updated_by) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET guide=excluded.guide,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP',[i.id,guide,req.user.id]);await audit(req,'instrument_guide_'+(guide&&guide!==i.guide?'updated':'reset'));res.json({ok:true})}));
// ---- Delivery of the report, devolutiva PDF and the audit trail ----
const DELIVERY_MODES=['presencial','impresso','digital'];
app.put('/api/evaluations/:id/delivery',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);if(e.status!=='approved')throw fail(409,'Aprove o laudo antes de registrar a entrega');if(req.body?.clear===true){await pool.execute('UPDATE evaluations SET delivered_at=NULL,delivered_to=NULL,delivery_mode=NULL,delivered_by=NULL WHERE id=?',[e.id]);await audit(req,'delivery_cleared',e.id);return res.json({delivered_at:null})}const date=/^\d{4}-\d{2}-\d{2}$/.test(req.body?.date||'')?req.body.date:new Date().toISOString().slice(0,10);const to=String(req.body?.delivered_to||'').replace(/\s+/g,' ').trim().slice(0,160);if(to.length<2)throw fail(400,'Informe para quem o laudo foi entregue');const mode=DELIVERY_MODES.includes(req.body?.mode)?req.body.mode:'presencial';await pool.execute('UPDATE evaluations SET delivered_at=?,delivered_to=?,delivery_mode=?,delivered_by=? WHERE id=?',[date,to,mode,req.user.id,e.id]);await audit(req,'report_delivered',e.id);res.json({delivered_at:date,delivered_to:to,delivery_mode:mode})}));
app.post('/api/evaluations/:id/devolutiva/export.pdf',auth,role('admin','psychologist'),wrap(async(req,res)=>{const e=await evaluation(req.params.id);const d=await devolutivaOf(e.id);if(d?.status!=='approved')throw fail(409,'Aprove a devolutiva antes de baixar');await fs.mkdir(STORAGE,{recursive:true,mode:0o700});const out=path.join(STORAGE,randomUUID()+'.docx');try{await docx('letter',[],{out,title:'Devolutiva da avaliação neuropsicológica',subtitle:e.patient_name,content:d.content});const pdf=await toPdf(await fs.readFile(out));await audit(req,'devolutiva_export_pdf',e.id);res.set('Content-Type','application/pdf');res.set('Content-Disposition','attachment; filename="devolutiva.pdf"');res.send(pdf)}finally{await fs.rm(out,{force:true})}}));
// Audit trail (admin): who created, opened, edited, approved, downloaded or deleted what. Only actions, never content.
app.get('/api/audit',auth,role('admin'),wrap(async(req,res)=>{const where=[],args=[];const q=req.query;if(q.user){where.push('a.actor_id=?');args.push(String(q.user))}if(q.evaluation){where.push('a.evaluation_id=?');args.push(String(q.evaluation))}if(q.action){where.push('a.action LIKE ?');args.push('%'+String(q.action).replace(/[%_]/g,'')+'%')}if(/^\d{4}-\d{2}-\d{2}$/.test(q.from||'')){where.push('a.created_at>=?');args.push(q.from)}if(/^\d{4}-\d{2}-\d{2}$/.test(q.to||'')){where.push('a.created_at<?');args.push(new Date(Date.parse(q.to)+864e5).toISOString().slice(0,10))}const w=where.length?'WHERE '+where.join(' AND '):'';const limit=Math.min(Math.max(Number(q.limit)||100,1),500),offset=Math.max(Number(q.offset)||0,0);const [[{n}]]=await pool.execute('SELECT COUNT(*) n FROM audit_logs a '+w,args);const [rows]=await pool.execute('SELECT a.id,a.action,a.created_at,a.evaluation_id,u.name actor_name,u.email actor_email,p.name patient_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id LEFT JOIN evaluations e ON e.id=a.evaluation_id LEFT JOIN patients p ON p.id=e.patient_id '+w+' ORDER BY a.id DESC LIMIT '+limit+' OFFSET '+offset,args);const [users]=await pool.query('SELECT id,name FROM users ORDER BY name');res.json({total:Number(n),rows,users})}));
// ---- Two-step verification (authenticator app). The secret is stored encrypted with the file key. ----
const totpSeal=secret=>encrypt(Buffer.from(secret)).toString('base64');
const totpSecretOf=sealed=>decrypt(Buffer.from(String(sealed||''),'base64')).toString('utf8');
app.post('/api/me/mfa/setup',auth,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);if(u.totp_enabled_at)throw fail(409,'A verificação em duas etapas já está ativa');const secret=newSecret();await pool.execute('UPDATE users SET totp_pending=? WHERE id=?',[totpSeal(secret),u.id]);res.set('Cache-Control','no-store');res.json({secret,uri:otpauthUri(u.email,secret)})}));
app.post('/api/me/mfa/enable',auth,authLimiter,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);if(!u.totp_pending)throw fail(409,'Comece pela configuração');const secret=totpSecretOf(u.totp_pending);const step=verifyTotp(secret,req.body?.code);if(step===null)throw fail(400,'Código inválido. Digite o código que aparece agora no aplicativo.');await pool.execute('UPDATE users SET totp_secret=totp_pending,totp_pending=NULL,totp_enabled_at=CURRENT_TIMESTAMP,totp_last_step=? WHERE id=?',[step,u.id]);await audit(req,'user_mfa_enabled');const [[fresh]]=await pool.execute('SELECT * FROM users WHERE id=?',[u.id]);res.json(publicUser(fresh))}));
app.post('/api/me/mfa/disable',auth,authLimiter,wrap(async(req,res)=>{const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[req.user.id]);if(!u.totp_enabled_at)throw fail(409,'A verificação em duas etapas não está ativa');if(!await bcrypt.compare(String(req.body?.password||''),u.password_hash))throw fail(400,'Senha incorreta');if(verifyTotp(totpSecretOf(u.totp_secret),req.body?.code,Number(u.totp_last_step??-1))===null)throw fail(400,'Código inválido');await pool.execute('UPDATE users SET totp_secret=NULL,totp_pending=NULL,totp_enabled_at=NULL,totp_last_step=NULL WHERE id=?',[u.id]);await audit(req,'user_mfa_disabled');const [[fresh]]=await pool.execute('SELECT * FROM users WHERE id=?',[u.id]);res.json(publicUser(fresh))}));
// Lost phone: the admin turns it off for that person (open sessions end); they turn it on again with a new code.
app.post('/api/users/:id/mfa/reset',auth,role('admin'),wrap(async(req,res)=>{const u=await userRow(req.params.id);if(u.id===req.user.id)throw fail(409,'Para a sua própria conta, use Minha conta.');await pool.execute('UPDATE users SET totp_secret=NULL,totp_pending=NULL,totp_enabled_at=NULL,totp_last_step=NULL,token_version=token_version+1 WHERE id=?',[u.id]);await audit(req,'user_mfa_reset');res.json(publicUser(await userRow(u.id)))}));
// ---- Accounts (admin only). Accounts are deactivated, never deleted: audit rows and approvals keep pointing at them. ----
const activeAdminsBesides=async id=>Number((await pool.execute("SELECT COUNT(*) n FROM users WHERE role='admin' AND active=1 AND id<>?",[id]))[0][0].n);
async function userRow(id){const [[u]]=await pool.execute('SELECT * FROM users WHERE id=?',[String(id)]);if(!u)throw fail(404,'Usuário não encontrado');return u}
app.get('/api/users',auth,role('admin'),wrap(async(req,res)=>{const [rows]=await pool.query('SELECT u.*,(SELECT COUNT(*) FROM evaluations e WHERE e.created_by=u.id) evaluations,(SELECT COUNT(*) FROM evaluations e WHERE e.approved_by=u.id) approvals,(SELECT MAX(r.created_at) FROM password_requests r WHERE r.user_id=u.id AND r.handled_at IS NULL) reset_requested_at FROM users u ORDER BY u.active DESC,u.name');res.json({users:rows.map(u=>({...publicUser(u),evaluations:Number(u.evaluations),approvals:Number(u.approvals),reset_requested_at:u.reset_requested_at||null})),roles:ROLES.map(id=>({id,name:ROLE_NAMES[id]}))})}));
app.post('/api/users',auth,role('admin'),wrap(async(req,res)=>{const v=newUserInput(req.body);const [[dup]]=await pool.execute('SELECT id FROM users WHERE lower(email)=?',[v.email]);if(dup)throw fail(409,'Já existe uma conta com este e-mail');const id=randomUUID();await pool.execute('INSERT INTO users(id,email,name,password_hash,role,must_change_password) VALUES(?,?,?,?,?,1)',[id,v.email,v.name,await bcrypt.hash(v.password,12),v.role]);await audit(req,'user_created_'+v.role);res.status(201).json(publicUser(await userRow(id)))}));
