const ISO_DATE=/^\d{4}-\d{2}-\d{2}$/;
const toBr=iso=>ISO_DATE.test(iso||'')?iso.split('-').reverse().join('/'):'';
function fromBr(v){const m=String(v||'').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!m)return null;const iso=`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;const d=new Date(iso+'T00:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===iso?iso:null}
function ageText(birth,at){if(!ISO_DATE.test(birth||''))return '';const ref=ISO_DATE.test(at||'')?at:new Date().toISOString().slice(0,10);const [by,bm,bd]=birth.split('-').map(Number),[ry,rm,rd]=ref.split('-').map(Number);let y=ry-by;if(rm<bm||(rm===bm&&rd<bd))y--;if(y<0)return '';if(y<2){let mo=(ry-by)*12+rm-bm-(rd<bd?1:0);return mo===1?'1 mês':`${mo} meses`}return `${y} anos`}
// Values written into the base copy; empty ones leave the base text as it is.
function reportFields(e){return Object.fromEntries(Object.entries({'Nome':e.patient_name,'Data de Nascimento':toBr(e.birth_date),'Idade':ageText(e.birth_date,e.end_date),'Sexo':e.sex,'Escolaridade':e.schooling,'Data de início da avaliação':toBr(e.start_date),'Data da finalização do laudo':toBr(e.end_date),'__local_data':e.place_date}).filter(([,v])=>v&&String(v).trim()))}
