// ---- Text copied from the uploaded files (no AI, no cost) ----
// Descrição da demanda always comes from the base document as written. In a manual evaluation every section starts
// with what the files already say: the text under its field in the base document and, for the anamnesis, the
// anamnesis document when the base has none. Returns how many sections changed.
const FROM_FILE='from_file';
async function syncFromFile(e,key,text){
 text=(text||'').trim();
 const [[s]]=await pool.execute('SELECT id,version,status,source_summary,content FROM sections WHERE evaluation_id=? AND section_key=?',[e.id,key]);
 if(!s){if(!text)return 0;await pool.execute("INSERT INTO sections(id,evaluation_id,section_key,title,content,status,source_summary) VALUES(?,?,?,?,?,'edited',?)",[randomUUID(),e.id,key,key,text,FROM_FILE]);return 1}
 // a new file only replaces the untouched copy, never text the psychologist edited or generated
 if(s.source_summary!==FROM_FILE||s.version!==1||s.status==='approved'||s.content===text)return 0; if(text)await pool.execute('UPDATE sections SET content=? WHERE id=?',[text,s.id]);else await pool.execute('DELETE FROM sections WHERE id=?',[s.id]);
 return 1;
}
async function syncSectionsFromFiles(e,inspected,anamnesis){
 if(e.status==='approved')return 0;
 const fileText=k=>inspected?.markers?.find(m=>m.key===k)?.existing_text||'';
 let n=await syncFromFile(e,'demanda',fileText('demanda'));
 if(e.ai_mode!=='manual')return n;
 for(const k of SECTION_KEYS.filter(k=>k!=='demanda')){
  let t=fileText(k);
  if(!t.trim()&&k==='anamnesis'&&anamnesis)t=anamnesis.elements.filter(x=>x.type==='p'&&x.text).map(x=>x.text).join('\n\n');
  n+=await syncFromFile(e,k,t);
 }
 return n;
}
/** Only the demand (a new base file was uploaded); the other sections are synced when both files are read (inspect). */
async function syncDemandFromFile(e,inspected){
 if(e.status!=='approved')await syncFromFile(e,'demanda',inspected?.markers?.find(m=>m.key==='demanda')?.existing_text);
}
