// Anamnesis stays faithful to the report; interpretations also carry no numbers.
const wordingChecks=key=>({categories:key!=='anamnesis',numbers:INTERPRETATION_KEYS.includes(key)});
function classificationWarnings(key,text){const p=wordingProblems(text,wordingChecks(key));return p.length?['Texto contém '+p.join(' e ')+'. Revise antes de aprovar.']:[]}
const SECTION_KEYS=['demanda','anamnesis','inteligencia','percepcao','memoria','atencao','funcoes_executivas','comportamento','personalidade','comportamento_diva','conclusao','hipotese','recomendacoes'];
/** The diagnostic hypothesis is written by the psychologist only: the AI never drafts a diagnosis. */
const AI_SECTION_KEYS=SECTION_KEYS.filter(k=>k!=='hipotese');
/** Fixed parts of the base document under a heading box (worker fixed_blocks), rewritten by hand only. */
const FIXED_KEY_RE=/^fixo_[a-z0-9_]{2,60}$/;
const isSectionKey=k=>SECTION_KEYS.includes(k)||FIXED_KEY_RE.test(String(k));
const SECTION_NAMES={demanda:'Descrição da demanda',anamnesis:'Anamnese',inteligencia:'Habilidades intelectuais',percepcao:'Percepção',memoria:'Memória e aprendizagem',atencao:'Processos atencionais',funcoes_executivas:'Funções executivas',comportamento:'Comportamento',personalidade:'Bateria Fatorial da Personalidade',comportamento_diva:'Comportamento / DIVA',conclusao:'Conclusão',hipotese:'Hipótese diagnóstica',recomendacoes:'Indicações e recomendações'};
// Behaviour sub-sections not every base document has; old text in them is skipped, not an export error.
const OPTIONAL_KEYS=['personalidade','comportamento_diva','hipotese'];
const INTERPRETATION_KEYS=['inteligencia','percepcao','memoria','atencao','funcoes_executivas','comportamento','personalidade','comportamento_diva'];
// What each section reads from the base document; the reference tables on screen come from these same functions.
// Text the AI will replace is not evidence.
// A section without its interpretation field still has its tables after its title (title_ranges), for manual drafts.
function sectionElements(base,key){const m=base.markers.find(x=>x.key===key);const r=m?[m.section_start,m.section_end]:base.title_ranges?.[key];return r?base.elements.slice(r[0],r[1]).filter(x=>!x.replaceable):[]}
function resultTables(base){const at=k=>base.markers.find(m=>m.key===k)?.index;return base.elements.slice((at('anamnesis')??0)+1,at('conclusao')??base.elements.length).filter(x=>x.type==='table')}
const forAI=({grid,...element})=>element; // display-only layout stays out of the (paid) request
// Only the part of the base document a section needs is sent (data minimisation).
function sourceFor(key,base,ana,sections){
 const els=base.elements,markers=base.markers,anamnesis=ana.elements.filter(x=>x.type==='p'&&x.text).map(x=>x.text);
 const at=k=>markers.find(m=>m.key===k)?.index;
 if(key==='anamnesis')return {relato_da_entrevista:anamnesis};
 // Only the patient's part of the header: the report author's name, CRP, phone, training and place are not needed to write the demand.
 const identification=els.slice(0,at('demanda')??20).filter(x=>x.type==='p'&&x.text).map(x=>x.text).filter(t=>!/^\s*(identifica[çc][ãa]o do laudo|autora?|crp|crm|forma[çc][ãa]o|telefone|e-?mail|local de realiza[çc][ãa]o|data de in[íi]cio|data da finaliza[çc][ãa]o)\b/i.test(t));
 if(key==='demanda')return {identificacao:identification,relato_da_entrevista:anamnesis};
 if(INTERPRETATION_KEYS.includes(key)){
  // without its field, the section is drafted from the tables after its title (text stays out of the Word file)
  if(at(key)===undefined&&!base.title_ranges?.[key])throw fail(409,`A seção ${SECTION_NAMES[key]||key} não existe no arquivo base`);
  // Rule: a section is written only from its own topic (its tables and text in the base document), never from other sections or the anamnesis.
  return {trecho_da_secao:sectionElements(base,key).map(forAI)};
 }
 // The conclusion reads only the texts already written for the result sections (not demand, anamnesis or raw tables);
 // hidden BFP/DIVA text (no field in the base document) is left out.
 if(key==='conclusao'){const textos=Object.fromEntries(INTERPRETATION_KEYS.filter(k=>sections[k]?.trim()&&(!OPTIONAL_KEYS.includes(k)||at(k)!==undefined)).map(k=>[SECTION_NAMES[k],sections[k]]));if(!Object.keys(textos).length)throw fail(409,'Escreva ou gere os textos das seções antes da conclusão.');return {textos_das_secoes:textos}}
 const results=resultTables(base).map(forAI);
 return {identificacao:identification,anamnese:sections.anamnesis||anamnesis,interpretacoes:Object.fromEntries(INTERPRETATION_KEYS.filter(k=>sections[k]).map(k=>[k,sections[k]])),conclusao:sections.conclusao||null,tabelas_de_resultados:results};
}
// ---- AI cost tracking ----
// USD per 1M tokens [input, cached input, output]; override with OPENAI_PRICE_INPUT/_CACHED/_OUTPUT. Check openai.com/api/pricing.
const PRICES={'gpt-6-astra':[10.00,1.00,50.00],'gpt-6.1-sol':[2.00,0.10,10.00],'gpt-6.1-terra':[1.00,0.05,5.00],'gpt-6-luna':[0.10,0.01,0.50],'gpt-4.1-nano':[0.10,0.025,0.40],'gpt-4.1-mini':[0.40,0.10,1.60],'gpt-4.1':[2.00,0.50,8.00],'gpt-4o-mini':[0.15,0.075,0.60],'gpt-4o':[2.50,1.25,10.00]};
const USD_BRL=Number(process.env.USD_BRL||5.5);
// OPENAI_PRICES (JSON, e.g. {"gpt-6.1-terra":[1,0.05,5]}) updates prices per model without touching the code.
const PRICE_OVERRIDES=(()=>{try{return JSON.parse(process.env.OPENAI_PRICES||'{}')}catch{console.error('OPENAI_PRICES inválido: use JSON');return {}}})();
function priceFor(model){if(Array.isArray(PRICE_OVERRIDES[model]))return PRICE_OVERRIDES[model].map(Number);if(process.env.OPENAI_PRICE_INPUT&&process.env.OPENAI_PRICE_OUTPUT)return [Number(process.env.OPENAI_PRICE_INPUT),Number(process.env.OPENAI_PRICE_CACHED||process.env.OPENAI_PRICE_INPUT),Number(process.env.OPENAI_PRICE_OUTPUT)];const k=Object.keys(PRICES).sort((a,b)=>b.length-a.length).find(k=>model.startsWith(k));return k?PRICES[k]:null}
function costUsd(model,u){const p=priceFor(model);if(!p)return null;const cached=Math.min(u.cached||0,u.input);return ((u.input-cached)*p[0]+cached*p[1]+u.output*p[2])/1e6}
// Only counts, timing and status are stored: no text, prompt or patient data.
async function recordUsage(req,evaluationId,key,model,u){const usd=costUsd(model,u);await pool.execute('INSERT INTO ai_usage(evaluation_id,section_key,model,input_tokens,cached_tokens,output_tokens,reasoning_tokens,duration_ms,status,cost_usd,usd_brl,actor_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[evaluationId,key,model,u.input,u.cached,u.output,u.reasoning||0,u.ms??null,u.status||'ok',usd??0,USD_BRL,req.user?.id||null]);return {input_tokens:u.input,cached_tokens:u.cached,output_tokens:u.output,total_tokens:u.input+u.output,cost_usd:usd,cost_brl:usd===null?null:usd*USD_BRL,priced:usd!==null}}
async function usageSummary(where,args){const [[r]]=await pool.query(`SELECT COUNT(*) calls,COALESCE(SUM(input_tokens),0) input_tokens,COALESCE(SUM(output_tokens),0) output_tokens,COALESCE(SUM(cost_usd),0) cost_usd,COALESCE(SUM(cost_usd*usd_brl),0) cost_brl FROM ai_usage WHERE ${where}`,args);return {calls:Number(r.calls),input_tokens:Number(r.input_tokens),output_tokens:Number(r.output_tokens),total_tokens:Number(r.input_tokens)+Number(r.output_tokens),cost_usd:Number(r.cost_usd),cost_brl:Number(r.cost_brl)}}
// Breakdown of AI spending: per day, evaluation, section and model, plus the latest calls.
app.get('/api/ai/usage/details',auth,wrap(async(req,res)=>{
 const days=Math.min(Math.max(Number(req.query.days)||30,1),365);
 const since=new Date(Date.now()-days*864e5).toISOString().slice(0,10);
 const sum='COUNT(*) calls,COALESCE(SUM(u.input_tokens),0) input_tokens,COALESCE(SUM(u.cached_tokens),0) cached_tokens,COALESCE(SUM(u.output_tokens),0) output_tokens,COALESCE(SUM(u.reasoning_tokens),0) reasoning_tokens,COALESCE(AVG(u.duration_ms),0) avg_ms,SUM(CASE WHEN u.status=\'ok\' THEN 0 ELSE 1 END) failed,COALESCE(SUM(u.cost_usd),0) cost_usd,COALESCE(SUM(u.cost_usd*u.usd_brl),0) cost_brl';
 const q=async(sql,args=[since])=>(await pool.query(sql,args))[0].map(r=>({...r,total_tokens:Number(r.input_tokens)+Number(r.output_tokens)}));
 res.json({days,since,usd_brl:USD_BRL,
  byDay:await q(`SELECT date(u.created_at,'localtime') day,${sum} FROM ai_usage u WHERE u.created_at>=? GROUP BY day ORDER BY day DESC`),
  byEvaluation:await q(`SELECT u.evaluation_id,p.name patient_name,${sum},MAX(u.created_at) last_at FROM ai_usage u LEFT JOIN evaluations e ON e.id=u.evaluation_id LEFT JOIN patients p ON p.id=e.patient_id WHERE u.created_at>=? GROUP BY u.evaluation_id ORDER BY cost_usd DESC`),
  bySection:await q(`SELECT u.section_key,${sum} FROM ai_usage u WHERE u.created_at>=? GROUP BY u.section_key ORDER BY cost_usd DESC`),
  byModel:await q(`SELECT u.model,${sum} FROM ai_usage u WHERE u.created_at>=? GROUP BY u.model ORDER BY cost_usd DESC`),
  recent:(await pool.query(`SELECT u.created_at,u.section_key,u.model,u.input_tokens,u.cached_tokens,u.output_tokens,u.reasoning_tokens,u.duration_ms,u.status,u.cost_usd,u.cost_usd*u.usd_brl cost_brl,p.name patient_name FROM ai_usage u LEFT JOIN evaluations e ON e.id=u.evaluation_id LEFT JOIN patients p ON p.id=e.patient_id ORDER BY u.id DESC LIMIT 50`))[0]});
}));
