/** Instructions typed for this evaluation only. */
function evalInstructions(e){try{return JSON.parse(e.instructions_json||'{}')}catch{return {}}}
/** Instructions saved in the evaluation's report model (the starting point for every evaluation of that model). */
function modelInstructions(e){try{return JSON.parse(e.model_instructions_json||'{}')}catch{return {}}}
