 const tmp=path.join(STORAGE,randomUUID()+'.docx');
 try{await fs.writeFile(tmp,await readStorage(v.storage_path),{mode:0o600});const st={v:STRUCTURE_V,...docStructure(await docx('inspect',[tmp]))};await pool.execute('UPDATE report_model_versions SET structure_json=? WHERE id=?',[JSON.stringify(st),v.id]);return st}
