// ---- Read aloud: local neural voice (Piper, worker/tts_worker.py). Text never leaves the computer and is not logged. ----
const TTS_WORKER=path.join(path.dirname(WORKER||''),'tts_worker.py');
let tts=null;
function ttsProcess(){
 if(tts)return tts;
 const p=spawn(PYTHON,[TTS_WORKER],{windowsHide:true,stdio:['pipe','pipe','pipe']});
 const state={p,buf:Buffer.alloc(0),queue:[],chain:Promise.resolve()};
 p.stdout.on('data',d=>{state.buf=Buffer.concat([state.buf,d]);while(state.buf.length>=4){const n=state.buf.readUInt32BE(0);if(state.buf.length<4+n)break;const wav=state.buf.subarray(4,4+n);state.buf=state.buf.subarray(4+n);state.queue.shift()?.(n?Buffer.from(wav):null)}});
 p.stderr.on('data',d=>console.error('[tts]',String(d).slice(0,200)));
 const down=()=>{if(tts===state)tts=null;for(const r of state.queue.splice(0))r(null)};
 p.on('error',down);p.on('close',down);
 return tts=state;
}
function speak(text){const t=ttsProcess();const job=t.chain.then(()=>new Promise(resolve=>{t.queue.push(resolve);t.p.stdin.write(JSON.stringify({text})+'\n')}));t.chain=job.catch(()=>{});return job}
// Optional natural online voice (Microsoft Edge read-aloud, worker/tts_edge.py): sends the text to Microsoft, so it is
// used only when api/.env has TTS_PROVIDER=edge. Any failure falls back to the local Piper voice.
const TTS_EDGE=path.join(path.dirname(WORKER||''),'tts_edge.py');
// Long-lived edge worker (the Python package loads once); audio comes back in frames as Microsoft sends it.
let edge=null;
function edgeProcess(){
 if(edge)return edge;
 const p=spawn(PYTHON,[TTS_EDGE,'--serve'],{windowsHide:true,stdio:['pipe','pipe','pipe'],env:{...process.env,PYTHONIOENCODING:'utf-8'}});
 const state={p,buf:Buffer.alloc(0),job:null,chain:Promise.resolve()};
 p.stdout.on('data',d=>{state.buf=Buffer.concat([state.buf,d]);while(state.buf.length>=4){const n=state.buf.readUInt32BE(0);if(state.buf.length<4+n)break;const part=Buffer.from(state.buf.subarray(4,4+n));state.buf=state.buf.subarray(4+n);const j=state.job;if(!j)continue;if(n)j.chunk(part);else{state.job=null;j.done()}}});
 p.stderr.on('data',d=>console.error('[tts-edge]',String(d).slice(0,200)));
 const down=()=>{if(edge===state)edge=null;const j=state.job;state.job=null;j?.done()};
 p.on('error',down);p.on('close',down);
 return edge=state;
}
/** Streams the MP3 of one text: onChunk gets each piece; resolves with the number of bytes sent (0 = failed). */
function edgeStream(text,onChunk){
 const e=edgeProcess();
 const job=e.chain.then(()=>new Promise(resolve=>{let bytes=0;const timer=setTimeout(()=>{if(e.job===j){e.job=null;resolve(bytes)}},90000);
  const j={chunk:b=>{bytes+=b.length;onChunk(b)},done:()=>{clearTimeout(timer);resolve(bytes)}};e.job=j;e.p.stdin.write(JSON.stringify({text})+'\n')}));
 e.chain=job.catch(()=>{});return job;
}
