app.post('/api/models/:id/versions/:v/restore',auth,role('admin','psychologist'),wrap(async(req,res)=>{const m=await reportModel(req.params.id);const [[old]]=await pool.execute('SELECT * FROM report_model_versions WHERE model_id=? AND version=?',[m.id,Number(req.params.v)]);if(!old)throw fail(404,'Versão não encontrada');const bytes=await readStorage(old.storage_path);const report=await inspectModel(bytes,m.audience);const version=await addVersion(req,m.id,bytes,old.filename,`Restaurada da versão ${old.version}`,report);await audit(req,'model_version_restored');res.status(201).json({version,report})}));
app.get('/api/models/:id/versions/:v/file',auth,wrap(async(req,res)=>{const m=await reportModel(req.params.id);const [[v]]=req.params.v==='current'?[[await currentVersion(m.id)]]:await pool.execute('SELECT * FROM report_model_versions WHERE model_id=? AND version=?',[m.id,Number(req.params.v)]);if(!v)throw fail(404,'Versão não encontrada');await audit(req,'model_downloaded');res.set('Content-Type',DOCX_TYPE);res.set('Content-Disposition',`attachment; filename="modelo-v${v.version}.docx"`);res.send(await readStorage(v.storage_path))}));
app.get('/api/models/:id/instructions',auth,wrap(async(req,res)=>{const m=await reportModel(req.params.id);let own={};try{own=JSON.parse(m.instructions_json||'{}')}catch{}res.json({sections:await Promise.all(AI_SECTION_KEYS.map(async key=>({key,default:await defaultInstruction(key),model:own[key]||null,limit:WORD_LIMITS[key]})))})}));
app.put('/api/models/:id/instructions/:key',auth,role('admin','psychologist'),wrap(async(req,res)=>{const m=await reportModel(req.params.id);const key=req.params.key;if(!SECTION_KEYS.includes(key))throw fail(400,'Invalid section');let own={};try{own=JSON.parse(m.instructions_json||'{}')}catch{}const text=req.body?.prompt==null?'':String(req.body.prompt).trim();if(text&&(text.length<10||text.length>12000))throw fail(400,'Instrução deve ter entre 10 e 12.000 caracteres');if(text&&text!==await defaultInstruction(key))own[key]=text;else delete own[key];await pool.execute('UPDATE report_models SET instructions_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[JSON.stringify(own),m.id]);await audit(req,'model_instruction_updated_'+key);res.json({ok:true,model:own[key]||null})}));
app.post('/api/models/:id/duplicate',auth,role('admin','psychologist'),wrap(async(req,res)=>{const m=await reportModel(req.params.id);const cur=await currentVersion(m.id);if(!cur)throw fail(409,'O modelo não tem arquivo');const id=randomUUID();await pool.execute('INSERT INTO report_models(id,name,description,audience,tags_json,active,created_by,instructions_json) VALUES(?,?,?,?,?,?,?,?)',[id,(m.name+' (cópia)').slice(0,120),m.description,m.audience,m.tags_json,0,req.user.id,m.instructions_json||null]);await addVersion(req,id,await readStorage(cur.storage_path),cur.filename,`Cópia de "${m.name}" v${cur.version}`,JSON.parse(cur.report_json));await audit(req,'model_duplicated');res.status(201).json(modelRow(await reportModel(id),await currentVersion(id)))}));
app.delete('/api/models/:id',auth,role('admin','psychologist'),wrap(async(req,res)=>{const m=await reportModel(req.params.id);const [versions]=await pool.execute('SELECT storage_path FROM report_model_versions WHERE model_id=?',[m.id]);const conn=await pool.getConnection();try{await conn.beginTransaction();await conn.execute('UPDATE evaluations SET model_id=NULL WHERE model_id=?',[m.id]);await conn.execute('DELETE FROM report_model_versions WHERE model_id=?',[m.id]);await conn.execute('DELETE FROM report_models WHERE id=?',[m.id]);await conn.commit()}catch(err){await conn.rollback();throw err}finally{conn.release()}for(const v of versions)if(/^[a-f0-9-]+\.bin$/.test(v.storage_path))await fs.rm(path.join(STORAGE,v.storage_path),{force:true});await audit(req,'model_deleted');res.json({ok:true})}));
// ---- Ditado por voz: mints a short-lived client secret for a Realtime transcription session ----
// Audio and transcript go browser <-> OpenAI only; nothing of the dictation is stored or logged here (only that a session started).
const dictationLimiter=rateLimit({windowMs:10*60_000,limit:30,standardHeaders:'draft-7',legacyHeaders:false,message:{error:'Muitas sessões de ditado em sequência. Aguarde alguns minutos.'}});
const dictationModelOk=new Map();// model -> time of the last successful check (the account can lose access to it)
async function dictationUsedToday(userId){const [[r]]=await pool.execute("SELECT COUNT(*) n FROM audit_logs WHERE actor_id=? AND action='dictation_session' AND created_at>=strftime('%Y-%m-%dT00:00:00Z','now')",[userId]);return Number(r.n)}
app.get('/api/dictation/status',auth,wrap(async(req,res)=>{const cfg=dictationConfig();res.json({enabled:cfg.enabled,allowed:['admin','psychologist'].includes(req.user.role),reason:cfg.blockers[0]||null,model:cfg.model,max_seconds:cfg.maxSeconds,daily_limit:cfg.dailyLimit,used_today:await dictationUsedToday(req.user.id)})}));
app.post('/api/dictation/session',auth,role('admin','psychologist'),dictationLimiter,wrap(async(req,res)=>{
 res.set('Cache-Control','no-store');
 const cfg=dictationConfig();if(!cfg.enabled)throw fail(503,cfg.blockers[0]);
 if(await dictationUsedToday(req.user.id)>=cfg.dailyLimit)throw fail(429,`Limite diário de ${cfg.dailyLimit} sessões de ditado atingido (DICTATION_DAILY_LIMIT).`);
 const client=new OpenAI({apiKey:process.env.OPENAI_API_KEY});
 if(!(Date.now()-(dictationModelOk.get(cfg.model)||0)<10*60_000)){try{await client.models.retrieve(cfg.model);dictationModelOk.set(cfg.model,Date.now())}catch(err){throw fail(503,err?.status===404?`O modelo de transcrição ${cfg.model} não existe nesta conta da API OpenAI (ajuste DICTATION_MODEL).`:dictationError(err?.status||502,{error:{message:err?.message}}))}}
 let r;try{r=await fetch('https://api.openai.com/v1/realtime/client_secrets',{method:'POST',headers:{Authorization:'Bearer '+process.env.OPENAI_API_KEY,'Content-Type':'application/json','OpenAI-Safety-Identifier':safetyId(req.user.id)},body:JSON.stringify(clientSecretRequest(cfg)),signal:AbortSignal.timeout(15000)})}catch{throw fail(502,'Sem conexão com a OpenAI para abrir o ditado.')}
 const data=await r.json().catch(()=>({}));
 if(!r.ok||!data?.value){console.error('dictation_session',r.status,data?.error?.code||'');throw fail(r.ok?502:r.status===401?503:r.status>=500?502:r.status,dictationError(r.status,data))}
 await audit(req,'dictation_session',typeof req.body?.evaluation_id==='string'&&/^[a-f0-9-]{36}$/.test(req.body.evaluation_id)?req.body.evaluation_id:null);
 res.json({client_secret:data.value,expires_at:data.expires_at,model:cfg.model,max_seconds:cfg.maxSeconds});
}));
app.use((err,req,res,next)=>{console.error(err.code||'',err.message);if(err.code==='ERR_SQLITE_ERROR'&&/locked|busy/i.test(err.message))return res.status(503).json({error:'Banco ocupado. Tente novamente em instantes.'});if(err.code==='LIMIT_FILE_SIZE')return res.status(413).json({error:'Arquivo excede 15 MB'});res.status(err.status||500).json({error:err.status?err.message:'Erro interno. Consulte logs seguros.',...(err.report?{report:err.report}:{})})});
// Local convenience: ADMIN_EMAIL/ADMIN_PASSWORD in api/.env create the first admin when the users table is empty.
async function seedAdmin(){const email=process.env.ADMIN_EMAIL,password=process.env.ADMIN_PASSWORD;if(!email||!password||/REPLACE/.test(password))return;try{const [[{count}]]=await pool.query('SELECT COUNT(*) count FROM users');if(count)return;await pool.execute('INSERT INTO users(id,email,name,password_hash,role) VALUES(?,?,?,?,?)',[randomUUID(),email,'Administrador',await bcrypt.hash(password,12),'admin']);console.log(`Administrador padrão criado: ${email}`);if(password.length<14)console.warn('AVISO: senha do administrador padrão é fraca. Troque antes de usar dados reais ou acesso remoto.')}catch(e){console.error('Não foi possível criar o administrador padrão:',e.code||e.message)}}
// Columns added after a database file was first created (schema.sql creates new files complete).
async function ensureSchema(){pool.ensureColumns('evaluations',[['place_date','TEXT NULL']]);pool.ensureColumns('evaluations',[['ai_mode',"TEXT NOT NULL DEFAULT 'ai'"]]);pool.ensureColumns('ai_usage',[['reasoning_tokens','INTEGER NOT NULL DEFAULT 0'],['duration_ms','INTEGER NULL'],['status',"TEXT NOT NULL DEFAULT 'ok'"]]);pool.ensureColumns('evaluations',[['delivered_at','TEXT NULL'],['delivered_to','TEXT NULL'],['delivery_mode','TEXT NULL'],['delivered_by','TEXT NULL'],['submitted_at','TEXT NULL'],['submitted_by','TEXT NULL'],['consent_care_at','TEXT NULL'],['consent_ai_at','TEXT NULL'],['consent_by','TEXT NULL'],['consent_note','TEXT NULL']]);pool.ensureColumns('users',[['totp_secret','TEXT NULL'],['totp_pending','TEXT NULL'],['totp_enabled_at','TEXT NULL'],['totp_last_step','INTEGER NULL'],['active','INTEGER NOT NULL DEFAULT 1'],['token_version','INTEGER NOT NULL DEFAULT 0'],['must_change_password','INTEGER NOT NULL DEFAULT 0'],['last_login_at','TEXT NULL']]);pool.ensureColumns('ai_settings',[['credit_usd','REAL NULL'],['credit_at','TEXT NULL']]);pool.ensureColumns('evaluations',[['work_seconds','INTEGER NOT NULL DEFAULT 0'],['work_started_at','TEXT NULL'],['instructions_json','TEXT NULL'],['approved_by','TEXT NULL'],['approved_at','TEXT NULL'],['privacy_json','TEXT NULL'],['sex','TEXT NULL'],['schooling','TEXT NULL'],['start_date','TEXT NULL'],['end_date','TEXT NULL'],['model_id','TEXT NULL']]);pool.ensureColumns('sections',[['approved_by','TEXT NULL'],['approved_at','TEXT NULL'],['ai_text','TEXT NULL'],['content_html','TEXT NULL']]);pool.ensureColumns('evaluations',[['model_id','TEXT NULL']]);pool.ensureColumns('report_models',[['instructions_json','TEXT NULL']]);pool.ensureColumns('report_model_versions',[['structure_json','TEXT NULL']])}
ensureSchema().then(seedAdmin).catch(e=>console.error('Migração do banco falhou:',e.code||e.message));
// daily encrypted backup: first check a minute after start, then every hour
setTimeout(autoBackup,60_000).unref();setInterval(autoBackup,3600_000).unref();
console.log('Banco de dados: '+DB_FILE);
